"""
Textes des onglets FAQ / Glossaire / Code source, publiés dans data/content.json.

Seul le tableau des écarts mensuels de la FAQ « préindustriel » est reconstruit
à la volée depuis config.MONTHLY_OFFSETS ; le reste est du texte statique.
"""
from __future__ import annotations

import json

import config as C

_FRAGMENTS = json.loads(r"""{"fr":{"faq":[{"q":"Qu'est-ce que le Global Temperature Trend Monitor ?","a":"<p>Le Global Temperature Trend Monitor du Copernicus Climate Change Service (C3S) fournit chaque mois une mise à jour de la température globale de l'air en surface, ainsi qu'une indication du moment où le réchauffement mondial pourrait atteindre la limite de 1,5 °C fixée par l'accord de Paris sur le climat. À partir de tendances linéaires sur 30 ans, l'outil explore comment le niveau de réchauffement mondial par rapport aux températures préindustrielles a évolué depuis l'an 2000, et comment le rythme auquel nous nous approchons de 1,5 °C a évolué au cours du temps.</p>\n<p>Le Global Temperature Trend Monitor est avant tout un outil de suivi ; la date indicative n'est là qu'à titre d'illustration et ne doit pas être interprétée comme une prévision.</p>\n<p>Il permet simplement de :</p><ul>\n<li>suivre les variations mensuelles des températures globales de l'air en surface par rapport à la période préindustrielle ;</li>\n<li>visualiser le réchauffement mondial estimé à un instant donné depuis l'an 2000 ;</li>\n<li>voir, par l'extrapolation d'une tendance linéaire, une estimation de la date à laquelle le réchauffement mondial pourrait atteindre la limite de 1,5 °C fixée par l'accord de Paris ;</li>\n<li>explorer comment cette estimation varie selon les périodes de 30 ans utilisées pour le calcul de la tendance.</li></ul>"},{"q":"Comment utiliser l'application ?","a":"<p>L'application visualise, dans un graphique interactif en courbes, le changement de température observé depuis l'époque préindustrielle (1850-1900).</p>\n<p>Le curseur au-dessus du graphique peut être déplacé pour mettre en évidence la période de 30 ans précédant la date choisie. La plage s'étend de décembre 2000 au dernier mois disponible, avec un pas mensuel pour les douze derniers mois et un pas annuel pour le reste de la période.</p>\n<p>La période sélectionnée d'anomalies mensuelles de la température mondiale est représentée en orange.</p>\n<p>La ligne rouge épaisse représente la tendance linéaire sur la période de 30 ans sélectionnée, prolongée jusqu'au point où elle atteint un réchauffement mondial total de 1,5 °C ; cela donne une estimation de la date à laquelle la limite de 1,5 °C pourrait être franchie, si la tendance des 30 ans sélectionnés se poursuivait.</p>\n<p>La zone orange ombrée représente les données des projections climatiques fournies par le Groupe d'experts intergouvernemental sur l'évolution du climat (GIEC), formant une enveloppe d'incertitude illustrative autour de l'estimation du réchauffement issue de la réanalyse. Elle est fondée sur l'intervalle interquartile des modèles retenus par le GIEC dans son rapport spécial de 2018 sur le réchauffement de 1,5 °C.</p>\n<p>Le déplacement du curseur permet d'explorer l'évolution du rythme du réchauffement mondial depuis l'an 2000 et notre proximité de la limite de 1,5 °C.</p>"},{"q":"D'où viennent les données ?","a":"<p>Pour les changements de température observés, cette application utilise les données mensuelles de la température globale de l'air en surface de la réanalyse mondiale ERA5 produite par le C3S (premier jeu de données ci-dessous). Les anomalies mensuelles par rapport à la période de référence 1991-2020 sont calculées à partir d'une climatologie mensuelle ERA5 (second jeu de données ci-dessous). Cette climatologie inclut une correction de température sur les Grands Lacs américains. Les deux jeux de données sont disponibles dans le Climate Data Store (CDS) du C3S :</p><ul>\n<li><a href=\"https://cds.climate.copernicus.eu/datasets/reanalysis-era5-single-levels-monthly-means\">ERA5 monthly averaged data on single levels from 1940 to present</a> — « ERA5 est la cinquième génération de réanalyse de l'ECMWF pour le climat et la météo mondiaux des 8 dernières décennies. Les données sont disponibles à partir de 1940. ERA5 remplace la réanalyse ERA-Interim. La réanalyse combine données de modèle et observations du monde entier en un jeu de données globalement complet et cohérent… »</li>\n<li><a href=\"https://cds.climate.copernicus.eu/datasets/ecv-for-climate-change?tab=overview\">Essential climate variables for assessment of climate variability from 1979 to present</a> — « Ce jeu de données contient une sélection de climatologies, d'anomalies mensuelles et de champs de moyennes mensuelles de variables climatiques essentielles, adaptés au suivi et à l'évaluation de la variabilité et du changement climatiques… »</li></ul>\n<p>Des données issues de projections climatiques sont également utilisées pour fournir une enveloppe d'incertitude illustrative autour de l'estimation du réchauffement issue de la réanalyse. Ces données sont extraites de la figure 1 du résumé pour les décideurs du rapport spécial de 2018 du GIEC sur le réchauffement de 1,5 °C. Elles montrent l'évolution projetée de la température si les émissions de CO2 diminuaient progressivement pour atteindre zéro en 2055, tandis que les niveaux des autres gaz à effet de serre cessent d'augmenter après 2030. Les données sont utilisées dans l'application sans aucun contrôle qualité et leur présentation ici ne constitue pas une approbation du C3S.</p>"},{"q":"Quand l'application est-elle mise à jour ?","a":"<p>Cet outil est mis à jour automatiquement via GitHub Actions les <strong>4, 8 et 15 de chaque mois</strong>.</p>\n<p>Ce calendrier suit la disponibilité du jeu de données <a href=\"https://cds.climate.copernicus.eu/datasets/reanalysis-era5-single-levels-monthly-means\">ERA5 monthly averaged data on single levels from 1940 to present</a> dans le Climate Data Store, disponible autour du <strong>6 du mois</strong> pour le mois précédent.</p>"},{"q":"Comment l'écart par rapport à l'époque préindustrielle est-il calculé ?","a":"<p>ERA5 ne remontant qu'à 1940, un écart de température doit être appliqué pour convertir les anomalies globales de la période de référence 1991-2020 à la période préindustrielle 1850-1900. Cet écart reflète le changement moyen de température entre ces deux périodes, sur la base de plusieurs jeux de données remontant à 1850.</p>\n<p>Pour les moyennes annuelles et sur 12 mois, un écart constant de 0,88 °C est appliqué aux anomalies par rapport à 1991-2020, conformément à l'approche de l'OMM dans ses rapports sur l'état du climat mondial. Cette méthode est toutefois inadaptée aux anomalies mensuelles, en raison des différences saisonnières de rythme de réchauffement entre 1850-1900 et 1991-2020. On utilise donc des écarts mensuels, en supposant un rythme de réchauffement variant progressivement au fil de l'année. Ces écarts mensuels sont indiqués dans le tableau ci-dessous.</p>\n<p>De plus amples détails sur la méthode figurent dans le <a href=\"https://climate.copernicus.eu/climate-bulletins\">Bulletin climatique du C3S</a>.</p>\n<table><caption>Tableau 1 : écarts de température mensuels et moyen annuel (en °C) utilisés pour convertir les anomalies ERA5 (réf. 1991-2020) en anomalies par rapport à 1850-1900.</caption>{offsets_table}</table>"},{"q":"Quelles sont les limites de la méthodologie ?","a":"<p>Le modèle présenté ici n'a pas vocation à prédire l'avenir : c'est une illustration simple mais plausible de l'évolution possible du réchauffement mondial dans les années et décennies à venir. L'ajout d'autres jeux de données et de méthodes alternatives d'estimation de la tendance pourrait modifier légèrement les chiffres affichés, sans remettre en cause le fait qu'il s'agit d'une simplification et qu'un modèle plus complexe serait nécessaire pour couvrir l'ensemble des incertitudes. L'enveloppe d'incertitude donnée par les projections de modèles climatiques, ainsi que l'estimation probable indiquée par la barre orange du rapport du GIEC sur les 1,5 °C, reflète le niveau d'incertitude inhérent à une telle estimation.</p>"},{"q":"Comment citer les données et les images de ce site ?","a":"<p>Tous les utilisateurs des produits Copernicus doivent fournir une attribution claire et visible au programme Copernicus.</p>\n<p>Le <strong><a href=\"https://climate.copernicus.eu/\">Copernicus Climate Change Service (C3S)</a></strong> est mis en œuvre par l'<strong><a href=\"https://www.ecmwf.int/\">European Centre for Medium-Range Weather Forecasts (ECMWF)</a></strong> pour le compte de la Commission européenne et fait partie du programme spatial de l'Union européenne.</p>\n<p>Cet outil est un outil non officiel, non produit ni approuvé par Copernicus. Crédit suggéré : « Suivi du réchauffement mondial — seuil de 1,5 °C (d'après C3S/ECMWF, ERA5) » ; données : Copernicus Climate Change Service (C3S), réanalyse ERA5 ; projections : GIEC, rapport spécial de 2018.</p>"}],"glossary":[{"term":"Réchauffement mondial","def":"<p>Dans cette application, le <strong>réchauffement mondial</strong> à un instant donné désigne l'augmentation d'une moyenne sur 30 ans, centrée sur cet instant, de la température globale de surface de la Terre par rapport à la période préindustrielle.</p>"},{"term":"Limite de 1,5 °C","def":"<p>La limite de <strong>1,5 °C</strong> fixée par l'accord de Paris est un objectif pour la température moyenne de la planète sur une période de vingt ou trente ans. Pour plus d'informations, voir le <a href=\"https://unfccc.int/process-and-meetings/the-paris-agreement\">site de la Convention-cadre des Nations unies sur les changements climatiques (CCNUCC)</a>.</p>"},{"term":"Accord de Paris","def":"<p>L'<strong>accord de Paris</strong> est un traité international adopté en 2015 lors de la 21<sup>e</sup> Conférence des Parties (COP21) de la Convention-cadre des Nations unies sur les changements climatiques (CCNUCC). Pour plus d'informations, voir le <a href=\"https://unfccc.int/process-and-meetings/the-paris-agreement\">site de la CCNUCC</a>.</p>"},{"term":"Préindustriel","def":"<p>La période <strong>préindustrielle</strong> sert de référence aux objectifs de réchauffement mondial fixés par l'accord de Paris. Elle est généralement définie comme les 51 ans allant de 1850 à 1900 — la définition utilisée par cette application.</p>"},{"term":"Projections GIEC","def":"<p>Cette application inclut des <strong>projections climatiques</strong> fournies par le <strong>Groupe d'experts intergouvernemental sur l'évolution du climat (GIEC)</strong>, formant une enveloppe d'incertitude illustrative autour de l'estimation du réchauffement issue de la réanalyse. Elle est fondée sur l'intervalle interquartile des modèles retenus par le GIEC dans son <a href=\"https://www.ipcc.ch/sr15/\">rapport spécial de 2018</a> sur le réchauffement de 1,5 °C.</p>"},{"term":"Réanalyse climatique","def":"<p>Une <strong>réanalyse climatique</strong> est produite en combinant les sorties d'un modèle de prévision numérique du temps et des observations du système Terre collectées partout dans le monde (satellites, stations météo et autres instruments de l'atmosphère, de l'océan et du sol) grâce à une technique mathématique complexe appelée assimilation de données. Le résultat est un jeu de données globalement complet et temporellement cohérent couvrant plus de 80 ans, qui permet d'évaluer l'évolution à long terme du climat de la Terre.</p>"}],"source":"<h2>Code source</h2>\n<p>L'intégralité du code de cet outil est libre et disponible sur <strong><a href=\"https://github.com/Alliages/suivi-rechauffement-global\">GitHub — Alliages/suivi-rechauffement-global</a></strong>. L'application originale est celle du <a href=\"https://apps.climate.copernicus.eu/global-temperature-trend-monitor/\">Copernicus Climate Change Service</a>.</p>\n<h3>Résumé du fonctionnement</h3>\n<ul>\n<li><strong>Objectif :</strong> suivre chaque mois le réchauffement mondial (températures ERA5, C3S/ECMWF) face au seuil de 1,5 °C fixé par l'accord de Paris, et estimer — à titre purement indicatif — la date d'atteinte du seuil par extrapolation d'une tendance linéaire sur 30 ans. Ce n'est pas une prévision.</li>\n<li><strong>Données :</strong> anomalies mensuelles de la température globale (ERA5, référence 1991-2020, converties vers la période préindustrielle 1850-1900) et enveloppe d'incertitude issue des projections du GIEC (rapport spécial de 2018, SR15).</li>\n<li><strong>Traitement :</strong> un pipeline Python (dossier <code>pipeline/</code>) télécharge les données, calcule les tendances glissantes de 30 ans, la date d'atteinte et l'enveloppe, et génère <code>data/series.json</code>.</li>\n<li><strong>Mise à jour et déploiement :</strong> un workflow GitHub Actions (<code>.github/workflows/mise-a-jour.yml</code>) exécute le pipeline le 4, le 8 et le 15 de chaque mois, puis publie automatiquement le site statique sur GitHub Pages.</li>\n<li><strong>Stack :</strong> une page unique <code>index.html</code> (Plotly.js), sans dépendance à un service tiers.</li>\n</ul>"},"en":{"faq":[{"q":"What is the global temperature trend monitor?","a":"<p>The Copernicus Climate Change Service (C3S) global temperature trend monitor provides monthly updates on global surface air temperature, and an indication of when global warming might reach the 1.5 °C limit set out in the Paris Agreement on climate change. Using 30-year linear trends, the monitor explores how the level of global warming against pre-industrial temperatures has changed since the year 2000, and how the rate at which we approach the 1.5 °C has evolved over time.</p>\n<p>The global temperature trend monitor is first and foremost a monitoring tool, and the indicative future date is there for illustrative purposes only and should not be interpreted as a forecast.</p>\n<p>The global temperature trend monitor provides a simple way to:</p><ul>\n<li>Track the monthly changes in global surface air temperatures compared to the pre-industrial period;</li>\n<li>View the estimated global warming at a point in time over the past years;</li>\n<li>See an estimate, through the extrapolation of a linear trend, of when global warming might reach the 1.5 °C limit set by the Paris Agreement;</li>\n<li>Explore how this estimate changes based on different 30-year periods used for trend calculations.</li></ul>"},{"q":"How should the application be used?","a":"<p>The C3S global temperature trend monitor visualises the observed temperature change since pre-industrial times (1850-1900) in an interactive line graph.</p>\n<p>The slider above the graph can be moved to highlight the 30-year period leading up to the selected date. The range spans from December 2000 to the most recent available month, with a monthly frequency for the latest twelve months and a yearly frequency for the rest of the period.</p>\n<p>The selected 30-year period of monthly global temperature anomalies is shown in orange.</p>\n<p>The thick red line represents the linear trend over the selected 30-year period, extended all the way to the point at which it reaches total global warming of 1.5 °C; this provides an estimate of when the 1.5 °C limit might be breached, if the selected 30-year trend were to continue.</p>\n<p>The shaded orange area represents data from climate projections provided by the Intergovernmental Panel on Climate Change (IPCC), providing an illustrative envelope of uncertainty around the global warming estimate derived from reanalysis. This is based on the interquartile range of the set models chosen by the IPCC in the 2018 special report on global warming of 1.5 °C.</p>\n<p>Moving the slider back and forth allows you to explore how the rate of global warming has changed since the year 2000, and how close we are to reaching the 1.5 °C limit.</p>"},{"q":"Where do the data come from?","a":"<p>For observed temperature changes, this application uses monthly global surface air temperature data from the ERA5 global reanalysis produced by C3S (first dataset below). Monthly anomalies relative to the 1991-2020 reference period are calculated using an ERA5 monthly climatology (second dataset below). This climatology includes a temperature correction over the US Great Lakes. Both datasets are available in the C3S Climate Data Store (CDS):</p><ul>\n<li><a href=\"https://cds.climate.copernicus.eu/datasets/reanalysis-era5-single-levels-monthly-means\">ERA5 monthly averaged data on single levels from 1940 to present</a> — \"ERA5 is the fifth generation ECMWF reanalysis for the global climate and weather for the past 8 decades. Data is available from 1940 onwards. ERA5 replaces the ERA-Interim reanalysis. Reanalysis combines model data with observations from across the world into a globally complete and consistent datas…\"</li>\n<li><a href=\"https://cds.climate.copernicus.eu/datasets/ecv-for-climate-change?tab=overview\">Essential climate variables for assessment of climate variability from 1979 to present</a> — \"The Essential Climate Variables for assessment of climate variability from 1979 to present dataset contains a selection of climatologies, monthly anomalies and monthly mean fields of Essential Climate Variables (ECVs) suitable for monitoring and assessment of climate variability and change. Selectio…\"</li></ul>\n<p>Temperature data from climate projections are also used to provide an illustrative envelope of uncertainty around the global warming estimate derived from reanalysis. This data is extracted from Figure 1 in the summary for policymakers of the 2018 IPCC special report on global warming of 1.5 °C. It shows the projected temperature evolution if CO2 emissions gradually decrease to zero by 2055, while other greenhouse gas levels stop changing after 2030. Data are used in the application without any quality control and their representation here is not an endorsement by C3S.</p>"},{"q":"When is the global temperature trend monitor updated?","a":"<p>This tool is automatically updated via GitHub Actions on the <strong>4th, 8th and 15th of each month</strong>.</p>\n<p>This is in line with the availability of the <a href=\"https://cds.climate.copernicus.eu/datasets/reanalysis-era5-single-levels-monthly-means\">ERA5 monthly averaged data on single levels from 1940 to present</a> dataset in the Climate Data Store, available from around the <strong>6th of each month</strong> for the previous month.</p>"},{"q":"How is the temperature change against pre-industrial times calculated?","a":"<p>Since ERA5 only extends back to 1940, a temperature offset must be applied to convert global temperature anomalies from the 1991-2020 reference period to the 1850-1900 pre-industrial period. This offset reflects the average temperature change between these two periods, based on several datasets going back to 1850.</p>\n<p>For annual and 12-month averages, a constant offset of 0.88 °C is applied to anomalies relative to 1991-2020, consistent with the WMO's approach in its State of the Global Climate reports. However, this method is inadequate for monthly anomalies due to seasonal differences in warming rates between 1850-1900 and 1991-2020. Therefore, monthly varying offsets are used, based on the assumption of a smoothly varying warming rate throughout the year. These monthly offsets are shown in the table below.</p>\n<p>More details about the method can be found on the <a href=\"https://climate.copernicus.eu/climate-bulletins\">C3S Climate Bulletin</a> pages.</p>\n<table><caption>Table 1: Monthly and annual mean temperature offsets (in °C) used to convert ERA5 anomalies relative to 1991-2020 to anomalies relative to 1850-1900.</caption>{offsets_table}</table>"},{"q":"What are the limitations of the methodology?","a":"<p>The model presented here is not intended as a prediction but rather as a simplified yet plausible illustration of how global warming may evolve in the coming years and decades. Introducing additional datasets and alternative methods for estimating the trend might slightly alter the numbers shown, but this would not change the fact that the model is a simplification and that a more complex model is needed to encompass the full range of uncertainties. The uncertainty envelope given by the projections made with climate models, as well as the likely estimate indicated by the orange bar from the IPCC 1.5 °C report, reflects the level of uncertainty inherent in making such a prediction.</p>"},{"q":"How should data and images from this website be cited?","a":"<p>All users of Copernicus Products must provide clear and visible attribution to the Copernicus programme.</p>\n<p>The <strong><a href=\"https://climate.copernicus.eu/\">Copernicus Climate Change Service (C3S)</a></strong> is implemented by the <strong><a href=\"https://www.ecmwf.int/\">European Centre for Medium-Range Weather Forecasts (ECMWF)</a></strong> on behalf of the European Commission and is part of the European Union's space programme.</p>\n<p>This is an unofficial tool, not produced or endorsed by Copernicus. Suggested credit: \"Global warming tracking — 1.5 °C threshold (after C3S/ECMWF, ERA5)\"; data: Copernicus Climate Change Service (C3S), ERA5 reanalysis; projections: IPCC, 2018 special report.</p>"}],"glossary":[{"term":"Global Warming","def":"<p>In this application, <strong>global warming</strong> at a point in time refers to the increase in a 30-year average, centred on the specified time, of Earth's global surface temperature relative to the pre-industrial period.</p>"},{"term":"1.5 °C limit","def":"<p>The <strong>1.5 °C</strong> limit set in the Paris Agreement is a target for the average temperature of the planet over a twenty or thirty-year period. For more information, see the <a href=\"https://unfccc.int/process-and-meetings/the-paris-agreement\">United Nations Framework Convention on Climate Change (UNFCCC) website</a>.</p>"},{"term":"Paris Agreement","def":"<p>The <strong>Paris Agreement</strong> is an international treaty adopted in 2015 during the 21st Conference of the Parties (COP21) to the United Nations Framework Convention on Climate Change (UNFCCC). For more information, see the <a href=\"https://unfccc.int/process-and-meetings/the-paris-agreement\">UNFCCC website</a>.</p>"},{"term":"Pre-industrial","def":"<p>The <strong>pre-industrial</strong> period is used as a reference for the global warming targets set in the Paris Agreement. It is commonly defined as the 51-year period from 1850 to 1900, which is the definition used by this application.</p>"},{"term":"IPCC projections","def":"<p>This application includes <strong>climate projections</strong> provided by the <strong>Intergovernmental Panel on Climate Change (IPCC)</strong>, providing an illustrative envelope of uncertainty around the global warming estimate derived from reanalysis. This is based on the interquartile range of the set models chosen by the IPCC in the <a href=\"https://www.ipcc.ch/sr15/\">2018 special report</a> on global warming of 1.5 °C.</p>"},{"term":"Climate reanalysis","def":"<p>A <strong>climate reanalysis</strong> is produced by combining the output from a numerical weather prediction model with observations of the Earth system from across the world (including those coming from satellites, weather stations, and other instruments in the atmosphere, ocean and on land) through a complex mathematical technique known as data assimilation. The result is a globally complete and temporally consistent dataset spanning more than 80 years, enabling us to assess long-term changes in Earth's climate.</p>"}],"source":"<h2>Source code</h2>\n<p>The complete code of this tool is free and available on <strong><a href=\"https://github.com/Alliages/suivi-rechauffement-global\">GitHub — Alliages/suivi-rechauffement-global</a></strong>. The original application is the <a href=\"https://apps.climate.copernicus.eu/global-temperature-trend-monitor/\">Copernicus Climate Change Service</a> one.</p>\n<h3>How it works</h3>\n<ul>\n<li><strong>Purpose:</strong> track global warming (ERA5 temperatures, C3S/ECMWF) against the 1.5 °C threshold set in the Paris Agreement on a monthly basis, and estimate — for illustration only — when the threshold would be reached by extrapolating a 30-year linear trend. This is not a forecast.</li>\n<li><strong>Data:</strong> monthly global temperature anomalies (ERA5, 1991-2020 reference, converted to the 1850-1900 pre-industrial period) and an uncertainty envelope from IPCC projections (2018 special report, SR15).</li>\n<li><strong>Processing:</strong> a Python pipeline (<code>pipeline/</code>) downloads the data, computes rolling 30-year trends, the crossing date and the envelope, and generates <code>data/series.json</code>.</li>\n<li><strong>Updates and deployment:</strong> a GitHub Actions workflow (<code>.github/workflows/mise-a-jour.yml</code>) runs the pipeline on the 4th, 8th and 15th of each month, then automatically publishes the static site to GitHub Pages.</li>\n<li><strong>Stack:</strong> a single <code>index.html</code> page (Plotly.js), with no third-party service dependency.</li>\n</ul>"}}""")

_MONTHS = {
    "fr": ["Jan", "Fév", "Mar", "Avr", "Mai", "Juin", "Juil", "Août", "Sep", "Oct", "Nov", "Déc"],
    "en": ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"],
}
_MONTHS_HEADER = {"fr": "Mois", "en": "Month"}
_ANNUAL_HEADER = {"fr": "Année", "en": "Annual Mean"}
_ROW_LABEL = {"fr": "Écart appliqué", "en": "Applied offset"}
_ANNUAL_OFFSET = 0.88


def _offsets_table(lang: str) -> str:
    """Ligne du tableau FAQ 5, générée depuis config.MONTHLY_OFFSETS."""
    heads = "".join(f"<th>{m}</th>" for m in _MONTHS[lang])
    values = "".join(f"<td>{v:.2f}</td>" for v in C.MONTHLY_OFFSETS)
    return (
        f'<thead><tr><th scope="col">{_MONTHS_HEADER[lang]}</th>{heads}'
        f'<th scope="col">{_ANNUAL_HEADER[lang]}</th></tr></thead>'
        f"<tbody><tr><td>{_ROW_LABEL[lang]}</td>{values}"
        f"<td>{_ANNUAL_OFFSET:.2f}</td></tr></tbody>"
    )


def build() -> dict:
    """Contenu complet {langue: {faq, glossary, source}} prêt pour le JSON."""
    out = json.loads(json.dumps(_FRAGMENTS))
    for lang, part in out.items():
        for item in part["faq"]:
            item["a"] = item["a"].replace("{offsets_table}", _offsets_table(lang))
    return out
